"""Regenerate docs/RULES.md from the rule catalog and the standards registry. Run with the project virtual environment."""
from pathlib import Path

from dbintel.cli import standards_coverage
from dbintel.rules.engine import load_catalog, load_standards


def _cell(text: str) -> str:
    return " ".join(str(text).split()).replace("|", "\\|")


def render() -> str:
    catalog = load_catalog()
    standards = load_standards()
    coverage = standards_coverage()
    lines = [
        "# Rules and standards",
        "",
        "Generated by `scripts/generate_rules_doc.py`. Do not edit by hand.",
        "",
        "## Coverage of the standards",
        "",
        f"The registry has {len(standards)} standards. Of these, {coverage['total_active_or_provisional']} are active or provisional; the rest are superseded.",
        "",
        "| Group | Count | Meaning |",
        "|---|---|---|",
        f"| Executable | {coverage['executable']} | At least one rule below enforces the standard. |",
        f"| Manual review | {coverage['manual_review']} | A person must judge it, for example a design record. The tool reports nothing about these. |",
        f"| Out of scope | {coverage['out_of_scope']} | It could be checked, but only with a running pipeline, monitor or migration tool that this version does not operate. |",
        "",
        "A rule that executes only proves the condition it checks. It does not certify the standard as a whole.",
        "",
        f"## Rules ({len(catalog)})",
        "",
        "| Rule | Severity | Kind | Category | Needs | Standards | Title |",
        "|---|---|---|---|---|---|---|",
    ]
    for rule in catalog:
        needs = ", ".join(rule.get("requires", [])) or "-"
        lines.append(f"| {rule['id']} | {rule['severity']} | {rule['kind']} | {rule['category']} | {needs} | {', '.join(rule['standards'])} | {_cell(rule['title'])} |")
    lines += ["", "## Executable standards", "", "| Standard | Status | Rules |", "|---|---|---|"]
    for sid, rules in coverage["executable_map"].items():
        lines.append(f"| {sid} | {standards[sid]['status']} | {', '.join(rules)} |")
    lines += ["", f"## Manual review standards ({coverage['manual_review']})", "", ", ".join(coverage["manual_review_ids"]) or "None."]
    lines += ["", f"## Out of scope standards ({coverage['out_of_scope']})", "", ", ".join(coverage["out_of_scope_ids"]) or "None.", ""]
    return "\n".join(lines)


def main() -> Path:
    target = Path(__file__).resolve().parent.parent / "docs" / "RULES.md"
    target.write_text(render(), encoding="utf-8")
    return target


if __name__ == "__main__":
    print(main())
